-- Guesswork (`guesswork@1`) and Gjeje (`gjeje@1`): the daily word, verified by the
-- database.
--
-- One hidden five-letter word a day and six guesses to find it; every guess must be a
-- word from the list, and fewer guesses score more. In Albanian the same game is
-- Gjeje, over Albanian words, as the crossword is Fjalekryqi: one catalogue entry,
-- one board, one ranked play a day across both languages.
--
--   1. The rules versions and the banks: each language's answers, in the order the
--      days walk them, and its other accepted guesses. Generated by
--      scripts/generate-guesswork-bank.mjs, which also writes
--      src/lib/games/guesswork-bank.ts.
--   2. `guesswork_decode(move)`: a move is a whole guess, five letters packed five
--      bits each, first letter lowest; codes 1–26 are A–Z, 27 Ç and 28 Ë.
--   3. `complete_guesswork_run` and `complete_gjeje_run`, the verifiers: the
--      generic gate, one completion a day (`already_played`), the replay, and
--      `speed_run_finish` with no par, so nothing is added to the replay's score.
--   4. The registry rows, and `start_game_session` giving a `guesswork` session the
--      player's day as its seed, as it does the crossword's.
--
-- Nothing a user can see changes: `20261222120100_guesswork_playable.sql` flips the
-- catalogue and lands last. Mirrored by src/lib/games/guesswork.ts. See
-- docs/games/README.md.

-- ─────────────────────────────────────────────────────────────────────────────
-- The rules and the banks
-- ─────────────────────────────────────────────────────────────────────────────

create or replace function public.guesswork_rules_version()
returns text language sql immutable set search_path = '' as $$ select 'guesswork@1'::text $$;

create or replace function public.gjeje_rules_version()
returns text language sql immutable set search_path = '' as $$ select 'gjeje@1'::text $$;

-- Six guesses, one move each.
create or replace function public.guesswork_max_actions()
returns integer language sql immutable set search_path = '' as $$ select 6 $$;

comment on function public.guesswork_rules_version() is
  'The English Guesswork rules version: guesswork@1.';
comment on function public.gjeje_rules_version() is
  'Gjeje, Guesswork in Albanian: gjeje@1.';
comment on function public.guesswork_max_actions() is
  'The most moves one Guesswork submission may carry: six guesses.';

