comment on function public.guesswork_answers() is
  'guesswork@1''s daily answers: day d is entry d mod n. Mirrored by src/lib/games/guesswork-bank.ts.';
comment on function public.gjeje_answers() is
  'gjeje@1''s daily answers: day d is entry d mod n. Mirrored by src/lib/games/guesswork-bank.ts.';

-- The day's word in a language's answers.
create or replace function public.guesswork_answer(p_answers text[], p_day bigint)
returns text
language sql
immutable
set search_path = ''
as $$
  select p_answers[((p_day % array_length(p_answers, 1)) + array_length(p_answers, 1))
                   % array_length(p_answers, 1) + 1]
$$;

comment on function public.guesswork_answer(text[], bigint) is
  'The day''s Guesswork word: answer day mod n.';

-- A move unpacked: five letters, code c being letter c of the alphabet below. Null
-- for a move that is not five letters.
create or replace function public.guesswork_decode(p_move integer)
returns text
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_letters constant text := 'ABCDEFGHIJKLMNOPQRSTUVWXYZÇË';
  v_word    text := '';
  v_code    integer;
  v_index   integer;
begin
  if p_move is null or p_move < 0 or p_move >= 33554432 then
    return null;
  end if;
  for v_index in 0..4 loop
    v_code := (p_move >> (5 * v_index)) & 31;
    if v_code < 1 or v_code > 28 then
      return null;
    end if;
    v_word := v_word || substr(v_letters, v_code, 1);
  end loop;
  return v_word;
end;
$$;

comment on function public.guesswork_decode(integer) is
  'A Guesswork move as its five-letter guess: codes 1–26 A–Z, 27 Ç, 28 Ë, five bits each, first letter lowest. Null when a code is not a letter.';

revoke all on function public.guesswork_answer(text[], bigint) from public;
revoke all on function public.guesswork_decode(integer) from public;

-- ─────────────────────────────────────────────────────────────────────────────
-- Complete a run: gate, replay, then record
-- ─────────────────────────────────────────────────────────────────────────────
--
-- Every move must be a word of the language's lists, played while the run is live:
-- the run is over once a guess is the answer or after the sixth. Solved on guess k,
-- the run scores (7 − k) × 10; unsolved, nothing. Stopping before either is the
-- player giving up, and is valid.

create or replace function public.guesswork_complete(
  p_session_id    uuid,
  p_actions       integer[],
  p_score         bigint,
  p_duration_ms   integer,
  p_rules_version text,
  p_answers       text[],
  p_guesses       text[]
)
returns public.play_result
language plpgsql
set search_path = ''
as $$
declare
  v_gate   record;
  v_result public.play_result;
  v_answer text;
  v_word   text;
  v_action integer;
  v_used   integer := 0;
  v_solved boolean := false;
  v_score  bigint := 0;
begin
  select * into v_gate from public.speed_run_gate(
    p_session_id, p_actions, p_score, p_duration_ms,
    p_rules_version, public.guesswork_max_actions());
  if (v_gate.refusal).outcome is not null then
    return v_gate.refusal;
  end if;

  v_result.session_id := (v_gate.session).id;
  v_result.game_slug := (v_gate.game).slug;

  -- One ranked play a day, in either language: the day is the seed.
  if (v_gate.session).user_id is not null and exists (
    select 1
      from public.game_sessions s
     where s.game_id = (v_gate.session).game_id
       and s.user_id = (v_gate.session).user_id
       and s.seed = (v_gate.session).seed
       and s.id <> (v_gate.session).id
       and s.completed_at is not null
  ) then
    v_result.outcome := 'already_played';
    return v_result;
  end if;

  v_answer := public.guesswork_answer(p_answers, (v_gate.session).seed);

  foreach v_action in array p_actions loop
    v_word := public.guesswork_decode(v_action);
    if v_solved or v_used >= 6 or v_word is null
       or not (v_word = any(p_answers) or v_word = any(p_guesses)) then
      v_result.outcome := 'invalid_actions';
      return v_result;
    end if;
    v_used := v_used + 1;
    v_solved := v_word = v_answer;
  end loop;

  if v_solved then
    v_score := (7 - v_used) * 10;
  end if;

  if p_score is distinct from v_score then
    v_result.outcome := 'score_mismatch';
    v_result.score := v_score;
    return v_result;
  end if;

  return public.speed_run_finish(
    v_gate.session, v_gate.game, v_gate.digest, v_score,
    0, v_gate.elapsed, case when v_solved then 1 else 0 end, v_used, p_duration_ms);
end;
$$;

revoke all on function public.guesswork_complete(uuid, integer[], bigint, integer, text, text[], text[]) from public;

create or replace function public.complete_guesswork_run(
  p_session_id  uuid,
  p_actions     integer[],
  p_score       bigint,
  p_duration_ms integer
)
returns public.play_result
language sql
security definer
set search_path = ''
as $$
  select public.guesswork_complete(
    p_session_id, p_actions, p_score, p_duration_ms,
    public.guesswork_rules_version(), public.guesswork_answers(), public.guesswork_guesses())
$$;

create or replace function public.complete_gjeje_run(
  p_session_id  uuid,
  p_actions     integer[],
  p_score       bigint,
  p_duration_ms integer
)
returns public.play_result
language sql
security definer
set search_path = ''
as $$
  select public.guesswork_complete(
    p_session_id, p_actions, p_score, p_duration_ms,
    public.gjeje_rules_version(), public.gjeje_answers(), public.gjeje_guesses())
$$;

comment on function public.complete_guesswork_run(uuid, integer[], bigint, integer) is
  'Replays a day''s Guesswork run — every guess a listed word — on the day''s word and records it: (7 − guesses) × 10 for a solve, nothing otherwise. One ranked completion per player per day (already_played). The claim is compared, never trusted.';
comment on function public.complete_gjeje_run(uuid, integer[], bigint, integer) is
  'Gjeje, Guesswork in Albanian: replays a day''s run on the day''s Albanian word and records it, as complete_guesswork_run does.';

revoke all on function public.complete_guesswork_run(uuid, integer[], bigint, integer) from public;
revoke all on function public.complete_gjeje_run(uuid, integer[], bigint, integer) from public;
grant execute on function public.complete_guesswork_run(uuid, integer[], bigint, integer) to anon, authenticated;
grant execute on function public.complete_gjeje_run(uuid, integer[], bigint, integer) to anon, authenticated;

-- ─────────────────────────────────────────────────────────────────────────────
-- The start gate learns Guesswork: two registry rows and a daily seed
-- ─────────────────────────────────────────────────────────────────────────────

insert into public.game_runtimes (runtime, rules_version, max_actions, session_hours) values
  ('guesswork', public.guesswork_rules_version(), public.guesswork_max_actions(), 2),
  ('guesswork', public.gjeje_rules_version(), public.guesswork_max_actions(), 2)
on conflict (runtime, rules_version) do update
  set max_actions   = excluded.max_actions,
      session_hours = excluded.session_hours;

-- The same function as `20261213120000_local_daily_reset.sql`, with `guesswork`
-- seeded by the player's day alongside the crossword.
create or replace function public.start_game_session(
  p_game_slug     text,
  p_rules_version text,
  p_client        text,
  p_time_zone     text
)
returns public.session_start
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_empty   public.session_start;
  v_game    public.games;
  v_user    uuid := auth.uid();
  v_client  text := nullif(btrim(coalesce(p_client, '')), '');
  v_session public.game_sessions;
  v_runtime public.game_runtimes;
  v_seed    bigint;
begin
  if p_game_slug is null or p_game_slug !~ '^[a-z0-9-]{2,48}$' then
    raise exception 'invalid game slug' using errcode = '22023';
  end if;
  if p_rules_version is null or p_rules_version !~ '^[a-z0-9-]{2,32}@[0-9]{1,4}$' then
    raise exception 'invalid rules version' using errcode = '22023';
  end if;
  if v_client is not null and char_length(v_client) > 40 then
    raise exception 'client is longer than 40 characters' using errcode = '22023';
  end if;

  select * into v_game
    from public.games g
   where g.slug = p_game_slug
     and g.status = 'published'
     and g.playable
     and g.runtime is not null;

  if not found then
    v_empty.outcome := 'not_playable';
    return v_empty;
  end if;

  -- The gate is a pair: each runtime plays the rules versions its verifier
  -- implements, as public.game_runtimes lists them. Anything else is a version
  -- no verifier owns.
  select * into v_runtime
    from public.game_runtimes r
   where r.runtime = v_game.runtime
     and r.rules_version = p_rules_version;

  if not found then
    v_empty.outcome := 'unsupported_runtime';
    return v_empty;
  end if;

  -- The daily games' seed is the player's day: the crossword's and Guesswork's is
  -- the day number, and 7 Second's is that number hashed exactly as
  -- `seven_second_seed` hashes it.
  if v_game.runtime in ('crossword', 'guesswork') then
    v_seed := public.player_local_day(p_time_zone);
  elsif v_game.runtime = 'seven-second' then
    v_seed := public.player_local_day(p_time_zone) * 2654435761 + 7;
  end if;

  if v_seed is not null and v_user is not null then
    perform pg_advisory_xact_lock(
      hashtextextended(v_game.id::text || ':' || v_user::text, 0)
    );

    if exists (
      select 1
        from public.game_sessions s
       where s.game_id = v_game.id
         and s.user_id = v_user
         and s.completed_at is not null
         and s.seed = v_seed
    ) then
      v_empty.outcome := 'already_played';
      return v_empty;
    end if;
  end if;

  if v_user is not null then
    update public.game_sessions s
       set abandoned_at = now()
     where s.game_id = v_game.id
       and s.user_id = v_user
       and s.completed_at is null
       and s.abandoned_at is null;
  end if;

  if v_seed is not null then
    insert into public.game_sessions (game_id, user_id, client, rules_version, seed)
    values (v_game.id, v_user, v_client, p_rules_version, v_seed)
    returning * into v_session;
  else
    -- An endless run is a marathon, so its session lives for twelve hours instead
    -- of the table's two; the registry says which.
    insert into public.game_sessions (game_id, user_id, client, rules_version, expires_at)
    values (v_game.id, v_user, v_client, p_rules_version,
            now() + make_interval(hours => v_runtime.session_hours))
    returning * into v_session;
  end if;

  v_empty.outcome       := 'started';
  v_empty.id            := v_session.id;
  v_empty.game_slug     := v_game.slug;
  v_empty.rules_version := v_session.rules_version;
  v_empty.seed          := v_session.seed;
  v_empty.tile_count    := v_runtime.max_actions;
  v_empty.started_at    := v_session.started_at;
  v_empty.expires_at    := v_session.expires_at;
  v_empty.ranked        := v_session.user_id is not null;
  return v_empty;
end;
$$;

comment on function public.start_game_session(text, text, text, text) is
  'Issues a play session with a server-chosen seed. The caller identity is the verified token, never an argument. A daily game''s seed (the crossword, Guesswork, 7 Second) follows the player''s own date.';

revoke all on function public.start_game_session(text, text, text, text) from public;
grant execute on function public.start_game_session(text, text, text, text) to anon, authenticated;
